style.css:
/* Importing the VERMIN VIVA font */
@font-face {
  font-family: 'VERMIN VIVA';
  src: url(https://fonts.googleapis.com/css2?family=Edu+AU+VIC+WA+NT+Pre:wght@400..700&family=Pacifico&display=swap) format('truetype');
}

/* Full-page styling */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body, html {
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: 'VERMIN VIVA', Arial, sans-serif;
  background: url(https://fonts.googleapis.com/css2?family=Edu+AU+VIC+WA+NT+Pre:wght@400..700&family=Pacifico&display=swap) no-repeat center center fixed;
  background-size: cover;
}

h1 {
  font-size: 5rem;
  color: #009e69; /* Text color */
  font-family: 'VERMIN VIVA', Arial, sans-serif;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.7);
}
